// 쉬운모드(투어 시작하기)용: '이동 (A → B)' 안내 트랙은 별도 작품이 아니라, 앞 장소의 moveTrack 으로 붙여
// 이동 화면에서 도면과 함께 보여준다.
const isMoveTrack = (a) => /^이동/.test(a.title);
export const vaticanEasyArtworks = vaticanTourData.artworks.reduce((list, a) => {
  if (!isMoveTrack(a)) return [...list, a];
  const prev = list[list.length - 1];
  if (!prev) return list;
  return [...list.slice(0, -1), { ...prev, moveTrack: { title: a.title, duration: a.duration, description: a.description, videoSrc: a.videoSrc, audioSrc: a.audioSrc } }];
}, []);

